code_example:
template <typename T>
T generic_add(T lhs, T rhs) {
    return lhs + rhs;
}

// Type deduction at call site
int i = generic_add(10, 5);

// Explicit template argument specification
float f = generic_add<float>(1.5f, 2.5f);

// Note: 'class' keyword can often replace 'typename'
template <class U>
U identity(U val) {
    return val;
}
